import {esc, cvHtml, tailoredCv, cvText, docx, download} from './documents.js';
import {APPLICATION_ANSWER_BANK} from './application-answer-bank.js';

const $=selector=>document.querySelector(selector), uid=()=>crypto.randomUUID(), copy=value=>structuredClone(value);
const KEY='checkchaser.workspace.v1', labels={eligible:'Verified fit',review:'Needs review',reject:'Not eligible',duplicate:'Duplicate',already_applied:'Already applied'};
const today=()=>new Date().toLocaleDateString('en-CA'), date=value=>value?new Date(value).toLocaleDateString('en-US',{month:'short',day:'numeric'}):'—';
const initial=()=>({version:1,policy:{minimum_base_usd:110000,target_ceiling_usd:360000,verification_max_age_hours:72},preferences:{dailyGoal:30,roles:'AI Product Manager; Technical Product Manager; AI deployment and program leadership',cities:'Remote United States first; then hybrid in Central Texas',voice:'Plain, confident and grounded in my real experience.'},integrations:{},cv:{name:'',contact:'',summary:{lead:'',body:''},sections:[{id:'experience',title:'EXPERIENCE',entries:[]},{id:'projects',title:'PROJECTS',entries:[]},{id:'education',title:'EDUCATION',entries:[]},{id:'skills',title:'SKILLS',entries:[]}]},applicationAnswers:copy(APPLICATION_ANSWER_BANK),cvVersion:1,jobs:[],history:[]});
let state=initial(), realState=null, demo=false, view='queue', filter='all', query='', current=null, pane='evidence', storageOk=true, feedSync={status:'loading',total:0,added:0,generated_at:null};
try {const raw=localStorage.getItem(KEY);if(raw)state=validateWorkspace(JSON.parse(raw));} catch {storageOk=false;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function save(){if(demo)return true;try{localStorage.setItem(KEY,JSON.stringify(state));storageOk=true;return true;}catch{storageOk=false;toast('Browser storage is unavailable. Export your workspace to keep your work.');return false;}}
let resumeImportRun=0;
const validCv=validateCv;
function validAnswerBank(items){if(!Array.isArray(items)||items.length>200)throw Error('The application answer bank must be an array of up to 200 records.');const ids=new Set();return items.map(item=>{if(!item||typeof item!=='object'||typeof item.id!=='string'||!/^[a-zA-Z0-9._-]{1,120}$/.test(item.id)||ids.has(item.id))throw Error('Every saved answer needs a unique safe ID.');ids.add(item.id);if(typeof item.question!=='string'||typeof item.answer!=='string')throw Error('Every saved answer needs a question and answer.');return {...item,category:String(item.category||'Application answer'),evidence:Array.isArray(item.evidence)?item.evidence.map(String):[],guardrail:String(item.guardrail||''),tags:Array.isArray(item.tags)?item.tags.map(String):[]};});}
function validateResearch(data){if(!data||!Array.isArray(data.jobs)||data.jobs.length>2000)throw Error('Use an agent research file with a jobs array (up to 2,000 roles).');if(data.jobs.some(j=>!j||typeof j!=='object'||Array.isArray(j)||typeof j.company!=='string'||typeof j.title!=='string'))throw Error('Each role needs a company and title.');if(data.history&&!Array.isArray(data.history))throw Error('History must be an array.');evaluate({jobs:data.jobs,history:data.history||[],policy:data.policy||state.policy});return data;}
function validateWorkspace(data){if(data?.version!==1||!Array.isArray(data.jobs)||!Array.isArray(data.history))throw Error('This is not a CheckChaser workspace backup.');validateResearch(data);data.cv=validCv(data.cv);data.applicationAnswers=validAnswerBank(data.applicationAnswers||APPLICATION_ANSWER_BANK);for(const record of [...data.jobs,...data.history])if(!record.id||!/^[a-zA-Z0-9_-]{1,80}$/.test(record.id))record.id=uid();return {...initial(),...data,preferences:{...initial().preferences,...data.preferences,dailyGoal:Math.max(1,Math.min(100,Number(data.preferences?.dailyGoal)||3))}};}
function results(){const active=state.jobs.filter(j=>!j.archived), r=evaluate({jobs:active,history:state.history,policy:{...state.policy,require_requirement_evidence:true}});return new Map(active.map((j,i)=>[j.id,r[i]]));}
function decision(job){return results().get(job.id)||{decision:'review',reasons:['Archived role'],notes:[]};}
function activeJobs(){return state.jobs.filter(j=>!j.archived);}
function stats(){const r=results();return {queue:activeJobs().filter(j=>!state.history.some(h=>same(j,h)&&['submitted','applied','interviewing','offer','rejected','withdrawn','submission-uncertain'].includes(h.status))).length,eligible:[...r.values()].filter(r=>r.decision==='eligible').length,review:[...r.values()].filter(r=>r.decision==='review').length,applied:state.history.filter(h=>['submitted','applied','interviewing','offer','rejected','withdrawn'].includes(h.status)).length,today:state.history.filter(h=>String(h.submitted_at||'').slice(0,10)===today() && h.status!=='submission-uncertain').length,due:state.history.filter(h=>h.followup && h.followup<=today() && ['submitted','applied','interviewing'].includes(h.status)).length};}
function same(a,b){const x=identities(a),y=identities(b);return [...x].some(k=>y.has(k));}
function mergePublishedResearch(data){validateResearch(data);let added=0,refreshed=0;for(const incoming of data.jobs){if(state.history.some(item=>same(item,incoming)))continue;const existing=state.jobs.find(item=>same(item,incoming));if(existing){const localFields={id:existing.id,selected:existing.selected,tailoring_note:existing.tailoring_note,material_version:existing.material_version,master_version:existing.master_version,material_approved:existing.material_approved,material_snapshot:existing.material_snapshot,answers:existing.answers,notes:existing.notes,preference_signal:existing.preference_signal,archived:existing.archived};Object.assign(existing,incoming,localFields);refreshed++;}else{state.jobs.push({...incoming,id:incoming.id&&/^[a-zA-Z0-9_-]{1,80}$/.test(incoming.id)?incoming.id:uid(),added_at:new Date().toISOString()});added++;}}return {added,refreshed};}
async function syncPublishedResearch(showToast=false){if(demo)return;feedSync={...feedSync,status:'loading'};try{const response=await fetch('/api/research?limit=2000',{headers:{accept:'application/json'},cache:'no-store'});if(!response.ok)throw Error('Research feed is not available.');const data=await response.json(),result=mergePublishedResearch(data);feedSync={status:'ready',total:Number(data.feed?.total??data.jobs.length),added:result.added,generated_at:data.generated_at||null};state.integrations={...(state.integrations||{}),research_feed_v1:true,research_feed_last_sync:new Date().toISOString(),research_feed_generated_at:data.generated_at||null};save();if(!document.querySelector('dialog[open]'))render();if(showToast)toast(result.added?result.added+' new verified roles added to your queue.':'Queue is current. No new verified roles.');}catch(error){feedSync={...feedSync,status:'unavailable',error:error.message};if(showToast)toast('The recurring research feed is temporarily unavailable.');}}
