 if(button.dataset.addEntry!==undefined){collectCv();state.cv.sections[button.dataset.addEntry].entries.push({id:uid(),org:'',role:'',place:'',dates:'',bullets:[{id:uid(),text:''}]});cvChanged();render();return;}
