 if(action==='import-cv'){
  let pending=null;const run=++resumeImportRun;
  const dialog=$('#resume-dialog'), input=$('#resume-file'), status=$('#resume-status'), preview=$('#resume-preview'), apply=$('#resume-apply');
  input.disabled=false;input.value='';status.textContent='PDF or DOCX, up to 8 MB. Optional CheckChaser JSON is also supported. Files are parsed in this browser.';preview.innerHTML='';apply.disabled=true;
  input.onchange=async()=>{pending=null;apply.disabled=true;preview.innerHTML='';if(!input.files[0])return;input.disabled=true;status.textContent='Reading resume…';try{const parsed=await importResume(input.files[0]);if(run!==resumeImportRun||!dialog.open)return;pending=parsed;status.textContent='Review the extracted facts below. Layouts can vary: check your name, contact details and section order. After importing, edit roles and dates in Master CV before tailoring.';preview.innerHTML=cvHtml(pending);apply.disabled=false;}catch(error){if(run===resumeImportRun&&dialog.open)status.textContent=error.message;}finally{if(run===resumeImportRun)input.disabled=false;}};
  apply.onclick=()=>{if(!pending)return;state.cv=pending;cvChanged();view='cv';dialog.close();render();toast('Resume imported. Review and edit the facts before tailoring.');};
  dialog.showModal();
 }

 if(action==='save-tailor'){const selected=[...document.querySelectorAll('[data-select-bullet]:checked')].map(el=>el.dataset.selectBullet);if(!selected.length)throw Error('Choose at least one source fact.');current.selected=selected;current.tailoring_note=$('#tailoring-note').value;current.material_version=(current.material_version||0)+1;current.master_version=state.cvVersion;current.material_approved=false;current.material_snapshot=tailoredCv(state.cv,selected);save();detail(current.id,'cv');toast('Tailored CV saved from your source facts.');}
